changeSet.sql:
CREATE UNIQUE INDEX uk_payouts_settlement_reference ON payouts (settlement_reference) WHERE settlement_reference IS NOT NULL AND is_deleted = false;
CREATE INDEX idx_payouts_awaiting_settlement ON payouts (created_at) WHERE is_deleted = false AND status IN ('PROCESSING');
ALTER TABLE payouts ADD CONSTRAINT chk_payouts_completed_requires_evidence CHECK (status <> 'COMPLETED' OR (settlement_reference IS NOT NULL AND provider_reference IS NOT NULL AND completed_at IS NOT NULL));

rollback.sql:
ALTER TABLE payouts DROP CONSTRAINT IF EXISTS chk_payouts_completed_requires_evidence;
DROP INDEX IF EXISTS idx_payouts_awaiting_settlement;
DROP INDEX IF EXISTS uk_payouts_settlement_reference;
